for a0 in 0..8:
    for a1 in 0..16:
        for a2 in 0..1024:
            in0 = load x0[a0, a2]
            in1 = load x1[a2, a1]
            v0 = multiply(in0, in1)
            acc0 <- add(acc0, v0) over a2
        matmul[a0, a1] = acc0

for a0 in 0..2:
    for a1 in 0..8:
        for a2 in 0..16:
            for a3 in 0..512 window(parent=a3 in 0..1024, partition=true):
                in0 = load x1[512 * a0 + a3, a2]
                in1 = load x0[a1, 512 * a0 + a3]
                v0 = multiply(in0, in1)
                acc0 <- add(acc0, v0) over a3
            matmul__partial[a0, a1, a2] = acc0

for a0 in 0..8:
    for a1 in 0..16:
        for a2 in 0..2 window(parent=a2 in 0..2, partition=true):
            in0 = load matmul__partial[a2, a0, a1]
            acc0 <- add(acc0, in0) over a2
        matmul[a0, a1] = acc0
